//! Style types: [`Style`], [`TextStyle`], [`ResolvedStyle`], [`StateFlags`],
//! and the [`StyleResolver`] that merges layered styles into a [`ResolvedStyle`].
//!
//! ## `merge` semantics
//!
//! `merge(base, next)` walks every `Option<_>` field of `base` and replaces
//! it with `next`'s value **only when `next` has `Some`**. The last layer
//! with a `Some` value wins. This is a top-of-stack "override on top"
//! merge, *not* a union.
//!
//! The 30+ `Option<_>` fields all follow the same pattern, so the merge
//! is generated by a single macro invocation — adding a field to `Style`
//! is a one-line change at the single `merge_style_fields!` call site.

use crate::{
    Align, Color, Display, Edge, GridPlacement, GridTrack, Length, Overflow, Paint, Position,
};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DefaultStyleMode {
    /// Full browser-like baseline (Block display, opacity 1.0).
    Full,
    /// Just the structural default (Block display).
    Minimal,
    /// No defaults at all.
    Reset,
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct StateFlags(u16);

impl StateFlags {
    pub const EMPTY: Self = Self(0);
    pub const HOVER: Self = Self(1 << 0);
    pub const FOCUS: Self = Self(1 << 1);
    pub const ACTIVE: Self = Self(1 << 2);
    pub const DISABLED: Self = Self(1 << 3);
    pub const CHECKED: Self = Self(1 << 4);
    pub const OPEN: Self = Self(1 << 5);
    pub const SELECTED: Self = Self(1 << 6);
    pub const INVALID: Self = Self(1 << 7);

    pub const fn contains(self, flag: Self) -> bool {
        self.0 & flag.0 == flag.0
    }

    pub const fn bits(self) -> u16 {
        self.0
    }

    pub const fn is_empty(self) -> bool {
        self.0 == 0
    }
}

impl std::ops::BitOr for StateFlags {
    type Output = Self;
    fn bitor(self, rhs: Self) -> Self::Output {
        Self(self.0 | rhs.0)
    }
}

impl std::ops::BitOrAssign for StateFlags {
    fn bitor_assign(&mut self, rhs: Self) {
        self.0 |= rhs.0;
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum FontWeight {
    Thin,
    ExtraLight,
    Light,
    Normal,
    Medium,
    Semibold,
    Bold,
    ExtraBold,
    Black,
    Number(u16),
}

impl Default for FontWeight {
    fn default() -> Self {
        FontWeight::Normal
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum FontStyle {
    Normal,
    Italic,
    Oblique,
}

impl Default for FontStyle {
    fn default() -> Self {
        FontStyle::Normal
    }
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum FontStretch {
    Condensed,
    Normal,
    Expanded,
    Percent(f32),
}

impl Default for FontStretch {
    fn default() -> Self {
        FontStretch::Normal
    }
}

#[derive(Clone, Debug, PartialEq)]
pub struct TextStyle {
    pub family: Vec<String>,
    pub size: Length,
    pub weight: FontWeight,
    pub style: FontStyle,
    pub stretch: FontStretch,
    /// Text fill color. Use [`Color::DEFAULT`] to mean "resolve from theme"
    /// at paint time — this is the default and is theme-aware.
    pub color: Color,
}

impl Default for TextStyle {
    fn default() -> Self {
        Self {
            family: vec!["system-ui".to_string()],
            size: Length::Px(14.0),
            weight: FontWeight::Normal,
            style: FontStyle::Normal,
            stretch: FontStretch::Normal,
            // Bug fix 1.5: previously hardcoded black, which was invisible on
            // dark themes. Color::DEFAULT is the "resolve at paint time from
            // the active theme" sentinel.
            color: Color::DEFAULT,
        }
    }
}

#[derive(Clone, Debug, PartialEq)]
pub enum Background {
    Paint(Paint),
}

impl Default for Background {
    fn default() -> Self {
        Background::Paint(Paint::Solid(Color::DEFAULT))
    }
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Border {
    pub color: Color,
    pub width: f32,
}

impl Default for Border {
    fn default() -> Self {
        Self {
            color: Color::DEFAULT,
            width: 1.0,
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Radius {
    pub top_left: f32,
    pub top_right: f32,
    pub bottom_right: f32,
    pub bottom_left: f32,
}

impl Radius {
    pub const fn all(value: f32) -> Self {
        Self {
            top_left: value,
            top_right: value,
            bottom_right: value,
            bottom_left: value,
        }
    }
}

impl Default for Radius {
    fn default() -> Self {
        Self::all(0.0)
    }
}

