#[derive(Clone, Debug, Default, PartialEq)]
pub struct Style {
    pub display: Option<Display>,
    pub position: Option<Position>,
    pub width: Option<Length>,
    pub height: Option<Length>,
    pub min_width: Option<Length>,
    pub max_width: Option<Length>,
    pub min_height: Option<Length>,
    pub max_height: Option<Length>,
    pub margin: Option<Edge<Length>>,
    pub padding: Option<Edge<Length>>,
    pub gap: Option<Length>,
    pub align_items: Option<Align>,
    pub align_self: Option<Align>,
    pub align_content: Option<Align>,
    pub justify_content: Option<crate::Justify>,
    pub flex_direction: Option<crate::FlexDirection>,
    pub flex_wrap: Option<crate::FlexWrap>,
    pub flex_grow: Option<f32>,
    pub flex_shrink: Option<f32>,
    pub flex_basis: Option<Length>,
    pub aspect_ratio: Option<f32>,
    pub inset: Option<Edge<Length>>,
    pub overflow_x: Option<Overflow>,
    pub overflow_y: Option<Overflow>,
    pub grid_template_columns: Option<Vec<GridTrack>>,
    pub grid_template_rows: Option<Vec<GridTrack>>,
    pub grid_column: Option<GridPlacement>,
    pub grid_row: Option<GridPlacement>,
    pub background: Option<Background>,
    pub border: Option<Border>,
    pub radius: Option<Radius>,
    pub shadow: Option<Vec<Shadow>>,
    pub opacity: Option<f32>,
    pub transform: Option<Transform>,
    pub z_index: Option<i32>,
    pub text: Option<TextStyle>,
    pub cursor: Option<CursorIcon>,
}

impl Style {
    pub fn new() -> Self {
        Self::default()
    }

    pub const fn display(mut self, value: Display) -> Self {
        self.display = Some(value);
        self
    }

    pub fn width(mut self, value: impl Into<Length>) -> Self {
        self.width = Some(value.into());
        self
    }

    pub fn height(mut self, value: impl Into<Length>) -> Self {
        self.height = Some(value.into());
        self
    }

    pub const fn opacity(mut self, value: f32) -> Self {
        self.opacity = Some(value);
        self
    }

    pub const fn z_index(mut self, value: i32) -> Self {
        self.z_index = Some(value);
        self
    }

    pub fn padding(mut self, value: impl Into<Length>) -> Self {
        let len = value.into();
        self.padding = Some(Edge::all(len));
        self
    }

    pub fn padding_edge(mut self, value: Edge<Length>) -> Self {
        self.padding = Some(value);
        self
    }

    pub fn font_weight(mut self, value: FontWeight) -> Self {
        let mut text = self.text.unwrap_or_default();
        text.weight = value;
        self.text = Some(text);
        self
    }

    pub fn background(mut self, value: Color) -> Self {
        self.background = Some(Background::Paint(Paint::Solid(value)));
        self
    }

    /// Returns `self` with `next`'s `Some` fields overriding `self`'s. Layers
    /// merge top‑down: the last `Some` for a field wins.
    pub fn merge_over(mut self, next: Style) -> Self {
        merge(&mut self, &next);
        self
    }
}

#[derive(Clone, Debug, PartialEq)]
pub struct ResolvedStyle {
    pub display: Display,
    pub position: Position,
    pub opacity: f32,
    pub z_index: i32,
    pub text: TextStyle,
    pub transform: Transform,
}

pub struct StyleResolver {
    mode: DefaultStyleMode,
}

impl StyleResolver {
    pub const fn new(mode: DefaultStyleMode) -> Self {
        Self { mode }
    }

    pub fn resolve_layers<I>(&self, layers: I) -> ResolvedStyle
    where
        I: IntoIterator<Item = Style>,
    {
        let mut merged = self.base_style();
        for layer in layers {
            merge(&mut merged, &layer);
        }
        ResolvedStyle {
            display: merged.display.unwrap_or(Display::Block),
            position: merged.position.unwrap_or(Position::Relative),
            opacity: merged.opacity.unwrap_or(1.0),
            z_index: merged.z_index.unwrap_or(0),
            text: merged.text.unwrap_or_default(),
            transform: merged.transform.unwrap_or_default(),
        }
    }

    fn base_style(&self) -> Style {
        match self.mode {
            DefaultStyleMode::Full => Style::default().display(Display::Block).opacity(1.0),
            DefaultStyleMode::Minimal => Style::default().display(Display::Block),
            DefaultStyleMode::Reset => Style::default(),
        }
    }
}

/// Generate the per-field "if `next.X` is `Some`, copy it into `base`"
/// merge body. The field list is co-located with this single call site
/// so adding a new field to `Style` is a one-line change here and one
/// new line in the struct.
macro_rules! merge_style_fields {
    ($base:ident, $next:ident) => {
        if $next.display.is_some() { $base.display = $next.display.clone(); }
        if $next.position.is_some() { $base.position = $next.position.clone(); }
        if $next.width.is_some() { $base.width = $next.width.clone(); }
        if $next.height.is_some() { $base.height = $next.height.clone(); }
        if $next.min_width.is_some() { $base.min_width = $next.min_width.clone(); }
        if $next.max_width.is_some() { $base.max_width = $next.max_width.clone(); }
        if $next.min_height.is_some() { $base.min_height = $next.min_height.clone(); }
        if $next.max_height.is_some() { $base.max_height = $next.max_height.clone(); }
        if $next.margin.is_some() { $base.margin = $next.margin.clone(); }
        if $next.padding.is_some() { $base.padding = $next.padding.clone(); }
        if $next.gap.is_some() { $base.gap = $next.gap.clone(); }
        if $next.align_items.is_some() { $base.align_items = $next.align_items.clone(); }
        if $next.align_self.is_some() { $base.align_self = $next.align_self.clone(); }
        if $next.align_content.is_some() { $base.align_content = $next.align_content.clone(); }
        if $next.justify_content.is_some() { $base.justify_content = $next.justify_content.clone(); }
        if $next.flex_direction.is_some() { $base.flex_direction = $next.flex_direction.clone(); }
        if $next.flex_wrap.is_some() { $base.flex_wrap = $next.flex_wrap.clone(); }
        if $next.flex_grow.is_some() { $base.flex_grow = $next.flex_grow.clone(); }
        if $next.flex_shrink.is_some() { $base.flex_shrink = $next.flex_shrink.clone(); }
        if $next.flex_basis.is_some() { $base.flex_basis = $next.flex_basis.clone(); }
        if $next.aspect_ratio.is_some() { $base.aspect_ratio = $next.aspect_ratio.clone(); }
        if $next.inset.is_some() { $base.inset = $next.inset.clone(); }
        if $next.overflow_x.is_some() { $base.overflow_x = $next.overflow_x.clone(); }
        if $next.overflow_y.is_some() { $base.overflow_y = $next.overflow_y.clone(); }
        if $next.grid_template_columns.is_some() { $base.grid_template_columns = $next.grid_template_columns.clone(); }
        if $next.grid_template_rows.is_some() { $base.grid_template_rows = $next.grid_template_rows.clone(); }
        if $next.grid_column.is_some() { $base.grid_column = $next.grid_column.clone(); }
        if $next.grid_row.is_some() { $base.grid_row = $next.grid_row.clone(); }
        if $next.background.is_some() { $base.background = $next.background.clone(); }
        if $next.border.is_some() { $base.border = $next.border.clone(); }
        if $next.radius.is_some() { $base.radius = $next.radius.clone(); }
        if $next.shadow.is_some() { $base.shadow = $next.shadow.clone(); }
        if $next.opacity.is_some() { $base.opacity = $next.opacity.clone(); }
        if $next.transform.is_some() { $base.transform = $next.transform.clone(); }
        if $next.z_index.is_some() { $base.z_index = $next.z_index.clone(); }
        if $next.text.is_some() { $base.text = $next.text.clone(); }
        if $next.cursor.is_some() { $base.cursor = $next.cursor.clone(); }
    };
}

fn merge(base: &mut Style, next: &Style) {
    merge_style_fields!(base, next);
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::Color;

    #[test]
    fn text_style_default_color_is_theme_sentinel() {
        // Bug fix 1.5: hardcoded black was invisible on dark themes.
        let s = TextStyle::default();
        assert!(s.color.is_default(), "default text color must be the theme sentinel");
    }

    #[test]
    fn merge_overrides_only_some_fields() {
        let base = Style::default().width(10.0).height(20.0);
        let next = Style::default().width(99.0); // height stays 20.0
        let merged = base.merge_over(next);
        assert_eq!(merged.width, Some(Length::Px(99.0)));
        assert_eq!(merged.height, Some(Length::Px(20.0)));
    }

    #[test]
    fn merge_later_layer_wins_on_some() {
        let a = Style::default().width(10.0);
        let b = Style::default().width(20.0).height(30.0);
        let c = Style::default().width(40.0);
        let merged = a.merge_over(b).merge_over(c);
        assert_eq!(merged.width, Some(Length::Px(40.0))); // c wins
        assert_eq!(merged.height, Some(Length::Px(30.0))); // b only
    }

    #[test]
    fn merge_with_none_keeps_base() {
        let base = Style::default()
            .width(10.0)
            .height(20.0)
            .opacity(0.5);
        let next = Style::default(); // all None
        let merged = base.merge_over(next);
        assert_eq!(merged.width, Some(Length::Px(10.0)));
        assert_eq!(merged.height, Some(Length::Px(20.0)));
        assert_eq!(merged.opacity, Some(0.5));
    }

    #[test]
    fn merge_is_idempotent_when_next_is_empty() {
        let base = Style::default().width(10.0).height(20.0).opacity(0.5);
        let next = Style::default();
        let merged_once = base.clone().merge_over(next.clone());
        let merged_twice = merged_once.clone().merge_over(next);
        assert_eq!(merged_once, merged_twice);
    }

    #[test]
    fn resolve_layers_uses_defaults_for_missing_fields() {
        let resolver = StyleResolver::new(DefaultStyleMode::Full);
        let resolved = resolver.resolve_layers(std::iter::empty());
        assert_eq!(resolved.display, Display::Block);
        assert_eq!(resolved.opacity, 1.0);
        assert_eq!(resolved.z_index, 0);
        assert!(resolved.text.color.is_default());
    }

    #[test]
    fn state_flags_bitor_assign() {
        let mut f = StateFlags::HOVER;
        f |= StateFlags::FOCUS;
        assert!(f.contains(StateFlags::HOVER));
        assert!(f.contains(StateFlags::FOCUS));
        assert!(!f.contains(StateFlags::ACTIVE));
        assert!(!f.is_empty());
    }
}
